package core.server;import java.sql.Connection;
/** Canonical runtime tables may not allocate node-local AUTO_INCREMENT identities. */
final class IdentitySchemaReadiness{private IdentitySchemaReadiness(){}static void verify(Connection connection,String catalog)throws Exception{String sql="SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=? AND EXTRA LIKE '%auto_increment%' AND (TABLE_NAME LIKE 'aoo\\_%' ESCAPE '\\\\' OR TABLE_NAME LIKE 'game\\_profile\\_%' ESCAPE '\\\\' OR TABLE_NAME LIKE 'admin\\_%' ESCAPE '\\\\')";try(var statement=connection.prepareStatement(sql)){statement.setString(1,catalog);try(var rows=statement.executeQuery()){if(rows.next())throw new IllegalStateException("canonical AUTO_INCREMENT is forbidden: "+rows.getString(1)+"."+rows.getString(2));}}}}
